 static readonly Regex SystemRx=new(@"^(?<ts>\d{2}\.\d{2}\.\d{4} \d{2}:\d{2}:\d{2}\.\d{3})\s+SYSTEM\s+(?<msg>.*)$",RegexOptions.Compiled);

 public SUBLogForm(string log,string db,string status,string config,Icon icon){logPath=log;dbPath=db;statusPath=status;configPath=config;Text="Traffic log";Icon=icon;Width=1250;Height=720;StartPosition=FormStartPosition.CenterScreen;Font=SystemFonts.MessageBoxFont??new Font("Segoe UI",9f);statusDotFont=new Font(Font.FontFamily,10f,FontStyle.Bold);pingFont=new Font(Font,FontStyle.Bold);serverDot.Font=new Font(Font.FontFamily,13f,FontStyle.Bold);BuildUi();EnableDoubleBuffering(filters);filters.ItemChecked+=(_,e)=>{if(refreshingFilters||e.Item==null||IsSeparator(e.Item))return;BeginInvoke((Action)Render);};filters.ItemSelectionChanged+=(_,e)=>{if(e.IsSelected&&e.Item!=null&&IsSeparator(e.Item))e.Item.Selected=false;};filters.Resize+=(_,_)=>ResizeFilterColumns();search.TextChanged+=(_,_)=>{clearSearch.Enabled=search.TextLength>0;Render();};clearSearch.Click+=(_,_)=>search.Clear();tail.CheckedChanged+=(_,_)=>ApplyTailMode();grid.SelectionChanged+=(_,_)=>{if(detail!=null&&!detail.IsDisposed)UpdateDetail();};grid.CellDoubleClick+=(_,e)=>{if(e.RowIndex>=0)OpenDetail();};grid.CellToolTipTextNeeded+=GridToolTip;Shown+=(_,_)=>BeginInvoke((Action)(()=>{ApplyInitialSplitterDistance();ResizeFilterColumns();AlignBottomControls();}));RefreshServiceNames();RefreshFilters();ApplyTailMode();Poll();timer.Tick+=(_,_)=>Poll();timer.Start();FormClosed+=(_,_)=>{timer.Stop();detail?.Close();statusDotFont.Dispose();pingFont.Dispose();};}

 void BuildUi(){
  var root=new TableLayoutPanel{Dock=DockStyle.Fill,RowCount=3,ColumnCount=1,Padding=new Padding(8)};root.RowStyles.Add(new RowStyle(SizeType.Absolute,30));root.RowStyles.Add(new RowStyle(SizeType.Percent,100));root.RowStyles.Add(new RowStyle(SizeType.AutoSize));
  var top=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=3,Margin=new Padding(0)};top.ColumnStyles.Add(new ColumnStyle(SizeType.AutoSize));top.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));top.ColumnStyles.Add(new ColumnStyle(SizeType.AutoSize));
  var statusPanel=new TableLayoutPanel{AutoSize=true,ColumnCount=2,RowCount=1,Margin=new Padding(0),Anchor=AnchorStyles.Left};statusPanel.ColumnStyles.Add(new ColumnStyle(SizeType.AutoSize));statusPanel.ColumnStyles.Add(new ColumnStyle(SizeType.AutoSize));serverDot.ForeColor=Color.Gray;serverDot.Anchor=AnchorStyles.None;serverDot.Margin=new Padding(0,0,4,0);serverText.Anchor=AnchorStyles.None;statusPanel.Controls.Add(serverDot,0,0);statusPanel.Controls.Add(serverText,1,0);top.Controls.Add(statusPanel,0,0);top.Controls.Add(new Panel{Dock=DockStyle.Fill},1,0);
  var searchPanel=new TableLayoutPanel{AutoSize=true,ColumnCount=2,RowCount=1,Margin=new Padding(0),Anchor=AnchorStyles.Right};searchPanel.ColumnStyles.Add(new ColumnStyle(SizeType.AutoSize));searchPanel.ColumnStyles.Add(new ColumnStyle(SizeType.AutoSize));search.Anchor=AnchorStyles.None;clearSearch.Anchor=AnchorStyles.None;searchPanel.Controls.Add(search,0,0);searchPanel.Controls.Add(clearSearch,1,0);top.Controls.Add(searchPanel,2,0);root.Controls.Add(top,0,0);
  split=new SplitContainer{Dock=DockStyle.Fill,FixedPanel=FixedPanel.Panel1};split.SplitterMoved+=(_,_)=>AlignBottomControls();
  var left=new TableLayoutPanel{Dock=DockStyle.Fill,RowCount=3,ColumnCount=1,Margin=new Padding(0)};left.RowStyles.Add(new RowStyle(SizeType.AutoSize));left.RowStyles.Add(new RowStyle(SizeType.Percent,100));left.RowStyles.Add(new RowStyle(SizeType.AutoSize));
  left.Controls.Add(new Label{Text="Message filters",AutoSize=true,Padding=new Padding(0,5,0,5),Margin=new Padding(0),BackColor=Color.Gainsboro,Dock=DockStyle.Fill},0,0);
  filters.Columns.Add("Service name",90,HorizontalAlignment.Left);filters.Columns.Add("Status",24,HorizontalAlignment.Center);left.Controls.Add(filters,0,1);filterError.Visible=false;left.Controls.Add(filterError,0,2);split.Panel1.Controls.Add(left);
  ConfigureGrid();split.Panel2.Controls.Add(grid);root.Controls.Add(split,0,1);
  var bottom=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=2,AutoSize=true,Margin=new Padding(0,6,0,0)};bottom.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));bottom.ColumnStyles.Add(new ColumnStyle(SizeType.AutoSize));tailHost=new FlowLayoutPanel{Dock=DockStyle.Fill,AutoSize=true,WrapContents=false,Margin=new Padding(0)};tailHost.Controls.Add(tail);bottom.Controls.Add(tailHost,0,0);var buttons=new FlowLayoutPanel{FlowDirection=FlowDirection.LeftToRight,WrapContents=false,AutoSize=true,Margin=new Padding(0)};var clear=new Button{Text="Clear",AutoSize=true};var cancel=new Button{Text="Cancel",AutoSize=true};clear.Click+=(_,_)=>ClearLog();cancel.Click+=(_,_)=>Close();buttons.Controls.Add(clear);buttons.Controls.Add(cancel);bottom.Controls.Add(buttons,1,0);root.Controls.Add(bottom,0,2);Controls.Add(root);
